class LegacySingleInputProcessorParticleAnalyzerTest {
    @TempDir Path tempDir;
    @Test void unrelatedProcessorParticleShapeIsProvenWithoutNames() throws Exception {var analysis=new LegacySingleInputProcessorParticleAnalyzer().analyze(jar(true),rule());assertTrue(analysis.diagnostics().isEmpty(),analysis.diagnostics().toString());var proof=analysis.proof().orElseThrow();assertEquals(0.2F,proof.blockVelocityMultiplier());assertEquals(0.6F,proof.blockScale());assertEquals(1,proof.itemParticleCount());assertEquals(0.15D,proof.itemVelocityYOffset());assertTrue(proof.metadataGated());assertTrue(proof.clientOnly());}
    @Test void missingSourceScaleCallFailsClosed() throws Exception {assertTrue(new LegacySingleInputProcessorParticleAnalyzer().analyze(jar(false),rule()).proof().isEmpty());}
    private Path jar(boolean complete)throws Exception{Path jar=tempDir.resolve(complete?"particle-ok.jar":"particle-bad.jar");try(JarOutputStream out=new JarOutputStream(Files.newOutputStream(jar))){out.putNextEntry(new JarEntry("foreign/particles/Tile.class"));out.write(tile(complete));out.closeEntry();}return jar;}
    private static LegacySingleInputProcessorAnalyzer.Rule rule(){return new LegacySingleInputProcessorAnalyzer.Rule("machine",null,"foreign/particles/Block","foreign/particles/Tile","Foreign",3,64,0,List.of(1,2),List.of(0),List.of(2,1),List.of(0),400,64.0,4,"foreign/particles/Recipes","lookup","(Lnet/minecraft/item/ItemStack;)Lforeign/particles/Recipe;",true,true,false);}
    private static byte[] tile(boolean complete){String owner="foreign/particles/Tile";ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,owner,null,"java/lang/Object",null);w.visitField(Opcodes.ACC_PUBLIC,"field_145850_b","Lnet/minecraft/world/World;",null,null).visitEnd();MethodVisitor meta=w.visitMethod(Opcodes.ACC_PUBLIC,"func_145832_p","()I",null,null);meta.visitCode();meta.visitInsn(Opcodes.ICONST_1);meta.visitInsn(Opcodes.IRETURN);meta.visitMaxs(0,0);meta.visitEnd();MethodVisitor tick=w.visitMethod(Opcodes.ACC_PUBLIC,"func_145845_h","()V",null,null);tick.visitCode();Label item=new Label(),done=new Label();tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitFieldInsn(Opcodes.GETFIELD,owner,"field_145850_b","Lnet/minecraft/world/World;");tick.visitFieldInsn(Opcodes.GETFIELD,"net/minecraft/world/World","field_72995_K","Z");tick.visitJumpInsn(Opcodes.IFEQ,done);tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitMethodInsn(Opcodes.INVOKEVIRTUAL,owner,"func_145832_p","()I",false);tick.visitJumpInsn(Opcodes.IFEQ,done);tick.visitInsn(Opcodes.ACONST_NULL);tick.visitTypeInsn(Opcodes.INSTANCEOF,"net/minecraft/item/ItemBlock");tick.visitJumpInsn(Opcodes.IFEQ,item);tick.visitTypeInsn(Opcodes.NEW,"net/minecraft/client/particle/EntityDiggingFX");tick.visitInsn(Opcodes.DUP);tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitFieldInsn(Opcodes.GETFIELD,owner,"field_145850_b","Lnet/minecraft/world/World;");for(int i=0;i<6;i++)tick.visitInsn(Opcodes.DCONST_0);tick.visitInsn(Opcodes.ACONST_NULL);tick.visitInsn(Opcodes.ICONST_0);tick.visitMethodInsn(Opcodes.INVOKESPECIAL,"net/minecraft/client/particle/EntityDiggingFX","<init>","(Lnet/minecraft/world/World;DDDDDDLnet/minecraft/block/Block;I)V",false);tick.visitInsn(Opcodes.ICONST_0);tick.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/client/particle/EntityDiggingFX","func_90019_g","(I)Lnet/minecraft/client/particle/EntityDiggingFX;",false);tick.visitLdcInsn(0.2F);tick.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/client/particle/EntityDiggingFX","func_70543_e","(F)Lnet/minecraft/client/particle/EntityFX;",false);tick.visitVarInsn(Opcodes.ASTORE,1);if(complete){tick.visitVarInsn(Opcodes.ALOAD,1);tick.visitLdcInsn(0.6F);tick.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/client/particle/EntityFX","func_70541_f","(F)Lnet/minecraft/client/particle/EntityFX;",false);tick.visitVarInsn(Opcodes.ASTORE,1);}tick.visitInsn(Opcodes.ACONST_NULL);tick.visitTypeInsn(Opcodes.CHECKCAST,"net/minecraft/client/particle/EffectRenderer");tick.visitVarInsn(Opcodes.ALOAD,1);tick.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/client/particle/EffectRenderer","func_78873_a","(Lnet/minecraft/client/particle/EntityFX;)V",false);tick.visitJumpInsn(Opcodes.GOTO,done);tick.visitLabel(item);tick.visitLdcInsn("iconcrack_");tick.visitInsn(Opcodes.POP);tick.visitInsn(Opcodes.ACONST_NULL);tick.visitTypeInsn(Opcodes.CHECKCAST,"net/minecraft/util/RegistryNamespaced");tick.visitInsn(Opcodes.ACONST_NULL);tick.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/util/RegistryNamespaced","func_148757_b","(Ljava/lang/Object;)I",false);tick.visitInsn(Opcodes.POP);tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitLdcInsn("iconcrack_1_0");tick.visitMethodInsn(Opcodes.INVOKESPECIAL,owner,"particle","(Ljava/lang/String;)V",false);tick.visitLabel(done);tick.visitInsn(Opcodes.RETURN);tick.visitMaxs(0,0);tick.visitEnd();MethodVisitor helper=w.visitMethod(Opcodes.ACC_PRIVATE,"particle","(Ljava/lang/String;)V",null,null);helper.visitCode();for(double value:new double[]{0.5D,0.1D,0.3D,0.6D,0.15D}){helper.visitLdcInsn(value);helper.visitInsn(Opcodes.POP2);}helper.visitMethodInsn(Opcodes.INVOKESTATIC,"java/lang/Math","random","()D",false);helper.visitInsn(Opcodes.POP2);helper.visitInsn(Opcodes.DCONST_0);helper.visitInsn(Opcodes.DCONST_0);helper.visitInsn(Opcodes.DCONST_0);helper.visitMethodInsn(Opcodes.INVOKESTATIC,"net/minecraft/util/Vec3","func_72443_a","(DDD)Lnet/minecraft/util/Vec3;",false);helper.visitVarInsn(Opcodes.ASTORE,2);helper.visitVarInsn(Opcodes.ALOAD,2);helper.visitInsn(Opcodes.FCONST_0);helper.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/util/Vec3","func_72440_a","(F)V",false);helper.visitVarInsn(Opcodes.ALOAD,2);helper.visitInsn(Opcodes.FCONST_0);helper.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/util/Vec3","func_72442_b","(F)V",false);helper.visitVarInsn(Opcodes.ALOAD,2);helper.visitInsn(Opcodes.DCONST_0);helper.visitInsn(Opcodes.DCONST_0);helper.visitInsn(Opcodes.DCONST_0);helper.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/util/Vec3","func_72441_c","(DDD)Lnet/minecraft/util/Vec3;",false);helper.visitVarInsn(Opcodes.ASTORE,2);helper.visitInsn(Opcodes.ICONST_0);helper.visitVarInsn(Opcodes.ISTORE,3);Label loop=new Label(),end=new Label();helper.visitLabel(loop);helper.visitVarInsn(Opcodes.ILOAD,3);helper.visitInsn(Opcodes.ICONST_1);helper.visitJumpInsn(Opcodes.IF_ICMPGE,end);helper.visitVarInsn(Opcodes.ALOAD,0);helper.visitFieldInsn(Opcodes.GETFIELD,owner,"field_145850_b","Lnet/minecraft/world/World;");helper.visitVarInsn(Opcodes.ALOAD,1);for(int i=0;i<6;i++)helper.visitInsn(Opcodes.DCONST_0);helper.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/world/World","func_72869_a","(Ljava/lang/String;DDDDDD)V",false);helper.visitIincInsn(3,1);helper.visitJumpInsn(Opcodes.GOTO,loop);helper.visitLabel(end);helper.visitInsn(Opcodes.RETURN);helper.visitMaxs(0,0);helper.visitEnd();w.visitEnd();return w.toByteArray();}
}
